module boomerang_4x4 (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [1:0] a0, a1, a2, a3,\n    output reg done,\n    output reg valid,\n    output reg target_valid,\n    output reg [2:0] target_row,\n    output reg [2:0] target_col\n);\n\n    // State declarations\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] PROCESS     = 3'd1;\n    localparam [2:0] OUTPUT      = 3'd2;\n    localparam [2:0] NEXT_COLUMN = 3'd3;\n    localparam [2:0] DONE        = 3'd4;\n    localparam [2:0] ERROR       = 3'd5;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [1:0] a_reg [0:3];\n    reg signed [2:0] col_index;\n    reg [1:0] sp_one;\n    reg [1:0] sp_two;\n    reg [1:0] stack_one_row [0:3];\n    reg [1:0] stack_one_col [0:3];\n    reg [1:0] stack_two_row [0:3];\n    reg [1:0] stack_two_col [0:3];\n    reg [1:0] target1_row, target1_col;\n    reg [1:0] target2_row, target2_col;\n    reg [1:0] remaining_targets;\n    reg [1:0] output_index;\n    integer i;  // Loop variable\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            valid <= 1'b0;\n            target_valid <= 1'b0;\n            target_row <= 3'd0;\n            target_col <= 3'd0;\n            col_index <= 3'd3;\n            sp_one <= 2'd0;\n            sp_two <= 2'd0;\n            remaining_targets <= 2'd0;\n            output_index <= 2'd0;\n            \n            // Initialize arrays\n            for (i = 0; i < 4; i = i + 1) begin\n                a_reg[i] <= 2'd0;\n                stack_one_row[i] <= 2'd0;\n                stack_one_col[i] <= 2'd0;\n                stack_two_row[i] <= 2'd0;\n                stack_two_col[i] <= 2'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    target_valid <= 1'b0;\n                    if (start) begin\n                        a_reg[0] <= a0;\n                        a_reg[1] <= a1;\n                        a_reg[2] <= a2;\n                        a_reg[3] <= a3;\n                        col_index <= 3'd3;\n                        sp_one <= 2'd0;\n                        sp_two <= 2'd0;\n                        state <= PROCESS;\n                    end\n                end\n\n                PROCESS: begin\n                    target_valid <= 1'b0;\n                    if ($signed(col_index) < 0) begin\n                        state <= DONE;\n                    end else begin\n                        case (a_reg[col_index])\n                            2'd0: begin\n                                state <= NEXT_COLUMN;\n                            end\n\n                            2'd1: begin\n                                if (sp_one < 2'd3) begin\n                                    stack_one_row[sp_one] <= col_index[1:0];\n                                    stack_one_col[sp_one] <= col_index[1:0];\n                                    sp_one <= sp_one + 2'd1;\n                                    target1_row <= col_index[1:0];\n                                    target1_col <= col_index[1:0];\n                                    remaining_targets <= 2'd1;\n                                    output_index <= 2'd0;\n                                    state <= OUTPUT;\n                                end else begin\n                                    state <= ERROR;\n                                end\n                            end\n\n                            2'd2: begin\n                                if (sp_one > 2'd0) begin\n                                    target1_row <= stack_one_row[sp_one - 2'd1];\n                                    target1_col <= col_index[1:0];\n                                    stack_two_row[sp_two] <= stack_one_row[sp_one - 2'd1];\n                                    stack_two_col[sp_two] <= col_index[1:0];\n                                    sp_two <= sp_two + 2'd1;\n                                    sp_one <= sp_one - 2'd1;\n                                    remaining_targets <= 2'd1;\n                                    output_index <= 2'd0;\n                                    state <= OUTPUT;\n                                end else begin\n                                    state <= ERROR;\n                                end\n                            end\n\n                            2'd3: begin\n                                if (sp_two > 2'd0) begin\n                                    target1_row <= col_index[1:0];\n                                    target1_col <= stack_two_col[sp_two - 2'd1];\n                                    target2_row <= col_index[1:0];\n                                    target2_col <= col_index[1:0];\n                                    stack_two_row[sp_two - 2'd1] <= col_index[1:0];\n                                    stack_two_col[sp_two - 2'd1] <= col_index[1:0];\n                                    remaining_targets <= 2'd2;\n                                    output_index <= 2'd0;\n                                    state <= OUTPUT;\n                                end else if (sp_one > 2'd0) begin\n                                    target1_row <= col_index[1:0];\n                                    target1_col <= stack_one_col[sp_one - 2'd1];\n                                    target2_row <= col_index[1:0];\n                                    target2_col <= col_index[1:0];\n                                    stack_two_row[sp_two] <= col_index[1:0];\n                                    stack_two_col[sp_two] <= col_index[1:0];\n                                    sp_two <= sp_two + 2'd1;\n                                    sp_one <= sp_one - 2'd1;\n                                    remaining_targets <= 2'd2;\n                                    output_index <= 2'd0;\n                                    state <= OUTPUT;\n                                end else begin\n                                    state <= ERROR;\n                                end\n                            end\n\n                            default: state <= NEXT_COLUMN;\n                        endcase\n                    end\n                end\n\n                OUTPUT: begin\n                    if (remaining_targets > 2'd0) begin\n                        target_valid <= 1'b1;\n                        if (output_index == 2'd0) begin\n                            target_row <= {1'b0, target1_row} + 3'd1;\n                            target_col <= {1'b0, target1_col} + 3'd1;\n                        end else begin\n                            target_row <= {1'b0, target2_row} + 3'd1;\n                            target_col <= {1'b0, target2_col} + 3'd1;\n                        end\n                        remaining_targets <= remaining_targets - 2'd1;\n                        output_index <= output_index + 2'd1;\n                    end else begin\n                        target_valid <= 1'b0;\n                        state <= NEXT_COLUMN;\n                    end\n                end\n\n                NEXT_COLUMN: begin\n                    col_index <= col_index - 3'd1;\n                    state <= PROCESS;\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    valid <= 1'b1;\n                    state <= IDLE;  // Return to idle after completion\n                end\n\n                ERROR: begin\n                    done <= 1'b1;\n                    valid <= 1'b0;\n                    state <= IDLE;  // Return to idle on error\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule